verts_exact=[[[Fraction(c) for c in vertex] for vertex in obj['vertices']] for obj in geometry['objects']]
def sub(first,second): return [a-b for a,b in zip(first,second)]
def dot(first,second): return sum(a*b for a,b in zip(first,second))
def cross(first,second): return [first[1]*second[2]-first[2]*second[1], first[2]*second[0]-first[0]*second[2], first[0]*second[1]-first[1]*second[0]]
panels=[]
for index,obj in enumerate(geometry['objects']):
 vertices=verts_exact[index]; triangles=obj['triangles']
 if len(vertices)!=4 or len(set(map(tuple,vertices)))!=4 or len(triangles)!=2: continue
 normals=[cross(sub(vertices[t[1]],vertices[t[0]]),sub(vertices[t[2]],vertices[t[0]])) for t in triangles]
 if dot(normals[0],normals[0])==0 or dot(normals[0],normals[1])<=0 or any(dot(normals[0],sub(vertex,vertices[0])) for vertex in vertices): continue
 edges={}
 for triangle in triangles:
  for start,end in zip(triangle,triangle[1:]+triangle[:1]):
   key=tuple(sorted((start,end))); edges[key]=edges.get(key,0)+1
 boundary=[edge for edge,count in edges.items() if count==1]
 if len(boundary)!=4 or len(edges)!=5: continue
 neighbors={vertex:[] for vertex in range(4)}
 for start,end in boundary: neighbors[start].append(end); neighbors[end].append(start)
 if any(len(adjacent)!=2 for adjacent in neighbors.values()): continue
 if any(dot(sub(vertices[adjacent[0]],vertices[vertex]),sub(vertices[adjacent[1]],vertices[vertex])) for vertex,adjacent in neighbors.items()): continue
 panels.append(index)
print('validated panels',[(index,geometry['objects'][index]['name']) for index in panels])
print('all other vertices above plane:',all(vertex[2]>0 for index,vertices in enumerate(verts_exact) if index not in panels for vertex in vertices))

def clip_polygon(polygon,axis,bound,keep_above):
 output=[]
 if not polygon: return output
 previous=polygon[-1]; prev_value=(previous[axis]-bound)*keep_above
 for current in polygon:
  value=(current[axis]-bound)*keep_above
  if (value>=0)!=(prev_value>=0):
   weight=prev_value/(prev_value-value)
   output.append([a+weight*(b-a) for a,b in zip(previous,current)])
  if value>=0: output.append(current)
  previous=current; prev_value=value
 return output

def twice_area(polygon):
 return abs(sum(first[0]*second[1]-first[1]*second[0] for first,second in zip(polygon,polygon[1:]+polygon[:1]))) if polygon else 0

geometric_results={}
for camera in cameras['views']:
 direction=list(map(Fraction,camera['direction_rational']))
 view_results={}
 for index in panels:
  vertices=verts_exact[index]; triangles=geometry['objects'][index]['triangles']
  normal=cross(sub(vertices[triangles[0][1]],vertices[triangles[0][0]]),sub(vertices[triangles[0][2]],vertices[triangles[0][0]]))
  front=dot(normal,direction)>0
  homogeneous=np.array([[float(c) for c in vertex]+[1.] for vertex in vertices])
  clip=homogeneous@np.array(camera['view_matrix']).T@np.array(camera['projection_matrix']).T
  ndc=clip[:,:3]/clip[:,3,None]
  inside=bool(np.all(np.abs(ndc)<=1))
  assert all(vertex[2]==0 for vertex in vertices)
  bounds=[(min(vertex[axis] for vertex in vertices),max(vertex[axis] for vertex in vertices)) for axis in (0,1)]
  blockers=[]
  for other,obj in enumerate(geometry['objects']):
   if other==index: continue
   blocked=False
   for triangle in obj['triangles']:
    points=[verts_exact[other][vertex] for vertex in triangle]
    if max(point[2] for point in points)<=0: continue
    points=clip_polygon(points,2,Fraction(0),1)
    shadow=[[point[axis]-point[2]*direction[axis]/direction[2] for axis in (0,1)] for point in points]
    for axis in (0,1):
     shadow=clip_polygon(shadow,axis,bounds[axis][0],1)
     shadow=clip_polygon(shadow,axis,bounds[axis][1],-1)
    if twice_area(shadow)>0:
     blocked=True; break
   if blocked: blockers.append(obj['name'])
  view_results[index]={'front':front,'inside':inside,'blockers':blockers,'complete':front and inside and not blockers}
 geometric_results[camera['name']]=view_results
print('geometry results',geometric_results)
rendered=render_views([camera['name'] for camera in cameras['views']],include_images=False)
print('rendered',rendered)

